import 'package:flutter/material.dart';
import 'package:uuid/uuid.dart';
import '../../core/backend.dart';
class ModulePage extends StatefulWidget {
  const ModulePage({super.key,required this.spec,required this.school,required this.ar,required this.canWrite});
  final RowData spec; final String school; final bool ar,canWrite;
  @override State<ModulePage> createState()=>_ModulePageState();
}
class _ModulePageState extends State<ModulePage> {
  List<RowData> rows=[]; Map<String,List<RowData>> relations={}; bool busy=true; String error='';
  List<RowData> get fields=>asRows(widget.spec['fields']); String get table=>widget.spec['table'] as String;
  @override void initState(){super.initState();load();}
  Future<void> load() async {setState((){busy=true;error='';});try{final r=asRows(await db.from(table).select().eq('school_id',widget.school).order('id').limit(200));final rel=<String,List<RowData>>{};for(final f in fields.where((f)=>f['kind']=='relation')){rel[f['name'] as String]=asRows(await db.from(f['table'] as String).select().eq('school_id',widget.school).order('id').limit(200));}if(mounted)setState((){rows=r;relations=rel;});}catch(e){if(mounted)setState(()=>error=e.toString());}finally{if(mounted)setState(()=>busy=false);}}
  String value(RowData row,String name){for(final f in fields){if(f['name']==name){for(final r in relations[name]??<RowData>[]){if(r['id']==row[name])return r[f['label']].toString();}}}return (row[name]??'').toString();}
  Future<void> open([RowData? row]) async {final saved=await Navigator.of(context).push<bool>(MaterialPageRoute(builder:(_)=>EditPage(spec:widget.spec,school:widget.school,ar:widget.ar,relations:relations,row:row)));if(saved==true&&mounted)await load();}
  @override Widget build(BuildContext context){final ar=widget.ar;final display=List<String>.from(widget.spec['display'] as List);return Scaffold(appBar:AppBar(title:Text(label(widget.spec,ar)),actions:[IconButton(onPressed:busy?null:load,icon:const Icon(Icons.refresh))]),floatingActionButton:widget.canWrite?FloatingActionButton(onPressed:busy?null:()=>open(),child:const Icon(Icons.add)):null,body:ListView(padding:const EdgeInsets.all(16),children:[if(busy)const LinearProgressIndicator(),if(error.isNotEmpty)Text(error),if(!busy&&rows.isEmpty&&error.isEmpty)Text(tr(ar,'لا توجد سجلات','No records')),...rows.map((r)=>Card(child:ListTile(title:Text(value(r,display.first)),subtitle:Text(display.skip(1).map((k)=>value(r,k)).join(' · ')),trailing:widget.canWrite&&widget.spec['rpc']==null?IconButton(onPressed:busy?null:()=>open(r),icon:const Icon(Icons.edit)):null))),Text(tr(ar,'الإصدار الأولي: أول 200 سجل فقط.','Pilot: first 200 records only.')),const SizedBox(height:80)]));}
}
class EditPage extends StatefulWidget {
  const EditPage({super.key,required this.spec,required this.school,required this.ar,required this.relations,this.row});
  final RowData spec;final String school;final bool ar;final Map<String,List<RowData>> relations;final RowData? row;
  @override State<EditPage> createState()=>_EditPageState();
}
class _EditPageState extends State<EditPage> {
  final formKey=GlobalKey<FormState>(); final values=<String,String>{}; final requestId=const Uuid().v4(); bool busy=false;String error='';
  List<RowData> get fields=>asRows(widget.spec['fields']);
  @override void initState(){super.initState();for(final f in fields){values[f['name'] as String]=(widget.row?[f['name']]??(f['options'] as List?)?.first??'').toString();}}
  Future<void> save()async{if(!formKey.currentState!.validate())return;setState((){busy=true;error='';});try{final data=<String,dynamic>{};for(final f in fields){final n=f['name'] as String;final v=values[n]!.trim();data[n]=f['kind']=='integer'?int.parse(v):f['kind']=='decimal'?num.parse(v):v;if(data[n] is num&&(!(data[n] as num).isFinite||data[n]<=0))throw const FormatException('Invalid number');}final rpc=widget.spec['rpc'];final table=widget.spec['table'] as String;if(rpc=='create_invoice'){await db.rpc('create_invoice',params:{'p_school':widget.school,'p_student':data['student_id'],'p_description':data['description'],'p_amount':data['amount'],'p_due_date':data['due_date']});}else if(rpc=='record_payment'){await db.rpc('record_payment',params:{'p_school':widget.school,'p_invoice':data['invoice_id'],'p_amount':data['amount'],'p_request':requestId});}else if(widget.row!=null){await db.from(table).update(data).eq('school_id',widget.school).eq('id',widget.row!['id']).select('id').single();}else{await db.from(table).insert({...data,'school_id':widget.school}).select('id').single();}if(mounted){setState(()=>busy=false);Navigator.pop(context,true);}}catch(e){if(mounted)setState(()=>error=e.toString());}finally{if(mounted)setState(()=>busy=false);}}
  @override Widget build(BuildContext context){final ar=widget.ar;return PopScope(canPop:!busy,child:Scaffold(appBar:AppBar(title:Text(widget.row==null?tr(ar,'إضافة','Add'):tr(ar,'تعديل','Edit'))),body:Form(key:formKey,child:ListView(padding:const EdgeInsets.all(16),children:[...fields.map((f){final n=f['name'] as String;final kind=f['kind'];final decoration=InputDecoration(labelText:label(f,ar),border:const OutlineInputBorder(),helperText:kind=='date'?'YYYY-MM-DD':null);String? requiredValue(String? v)=>f['optional']!=true&&(v==null||v.trim().isEmpty)?tr(ar,'مطلوب','Required'):null;final isChoice=kind=='relation'||kind=='select';final choices=kind=='relation'?(widget.relations[n]??<RowData>[]).map((r)=>DropdownMenuItem<String>(value:r['id'] as String,child:Text(r[f['label']].toString(),overflow:TextOverflow.ellipsis))).toList():kind=='select'?(f['options'] as List).map((o)=>DropdownMenuItem<String>(value:o.toString(),child:Text(o.toString()))).toList():<DropdownMenuItem<String>>[];return Padding(padding:const EdgeInsets.only(bottom:14),child:isChoice?DropdownButtonFormField<String>(isExpanded:true,initialValue:choices.any((c)=>c.value==values[n])?values[n]:null,items:choices,decoration:decoration,validator:requiredValue,onChanged:busy?null:(v)=>values[n]=v??''):TextFormField(initialValue:values[n],decoration:decoration,enabled:!busy,keyboardType:kind=='integer'||kind=='decimal'?const TextInputType.numberWithOptions(decimal:true):TextInputType.text,validator:requiredValue,onChanged:(v)=>values[n]=v));}),if(error.isNotEmpty)Text(error,style:TextStyle(color:Theme.of(context).colorScheme.error)),FilledButton(onPressed:busy?null:save,child:Text(tr(ar,'حفظ','Save'))),if(busy)const LinearProgressIndicator()]))));}
}
